import { SAMPLE_COLLECTIONS } from './sample.js';
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function initFeatures({state,$,modal,toast,replan,compute,useSample,updateMetrics,buildJobBody}) {
  const samples=SAMPLE_COLLECTIONS||[];
  $('browse-samples').onclick=()=>{
    modal('A whole library of possibility.',`<p>Try seven material collections. Pattern mix is a procedural FabricNet showcase with known grain angles; photo-style samples are AI generated. Scene widths are illustrative.</p><div class="sample-gallery">${samples.map(s=>`<button class="sample-choice" data-sample="${esc(s.id)}"><img src="${esc(s.src)}" alt="${esc(s.name)} fabric scraps" loading="lazy"><span class="sample-kind">${esc(s.tag)}</span><strong>${esc(s.name)}</strong><small>${esc(s.description)}</small></button>`).join('')}</div>`,'EXPLORE THE MATERIAL LIBRARY');
    $('dialog-content').querySelectorAll('[data-sample]').forEach(b=>b.onclick=async()=>{if(state.busy)return toast('Wait for the current analysis to finish.');$('info-dialog').close();await useSample(b.dataset.sample);toast('Sample loaded. Its scale is an illustrative assumption.');});
  };
  $('design-size').oninput=e=>{state.size=Number(e.target.value)/100;$('size-value').textContent=e.target.value+'%';clearTimeout(sizeTimer);sizeTimer=setTimeout(replan,160);};let sizeTimer;
  $('grain-rotation').onchange=e=>{state.rotation=e.target.checked;replan();};
  $('best-fit').onclick=async()=>{
    if(!state.analysis)return toast('Analyze your photo to find a suitable project.');if(state.busy)return toast('Wait for the current analysis to finish.');
    const b=$('best-fit');b.disabled=true;b.textContent='Checking your possibilities…';
    try{const {recommendations}=await compute('recommend');modal('Find a good fit for your fabric.',`<p>All three products are checked against your usable shapes, design size, seam allowance and rotation setting. Complete plans rank first, followed by measured material use.</p><div class="recommendations">${recommendations.map((r,i)=>`<div class="recommend-card"><div><span class="recommend-rank">${i===0&&r.feasible?'BEST FIT':'OPTION '+(i+1)}</span><h3>${esc(r.plan.title)}</h3><p>${esc(r.reason)}</p></div><button data-recommend="${r.product}" ${!r.feasible?'disabled':''}>${r.feasible?'Make this ↗':'More fabric needed'}</button></div>`).join('')}</div><p>These are geometry-based suggestions. Fabric condition and grain need a maker’s review.</p>`,'DESIGNED AROUND WHAT YOU HAVE');$('dialog-content').querySelectorAll('[data-recommend]').forEach(x=>x.onclick=()=>{state.product=x.dataset.recommend;document.querySelectorAll('[data-product]').forEach(p=>p.classList.toggle('selected',p.dataset.product===state.product));$('info-dialog').close();replan();});}catch(e){toast(e.message);}finally{b.disabled=false;b.innerHTML='Find my best fit <span>↗</span>';}
  };
  function reviewMaterial(s){state.selected=s.id;updateMetrics();const omitted=state.excluded.has(s.id);const issues=s.quality?.issues||[];modal('Give this piece a closer look.',`<div class="material-review"><div class="review-swatch" style="background-color:${esc(s.color)}"></div><div><h3>${esc(s.label)}</h3><p>${Math.round(s.areaCm2)} cm² detected · ${Math.round(s.usableAreaCm2)} cm² usable<br>Estimated bounding box: ${(s.bbox.width/s.pixelsPerCm).toFixed(1)} × ${(s.bbox.height/s.pixelsPerCm).toFixed(1)} cm</p></div></div><p>${issues.length?issues.map(esc).join(' '):'A complete boundary was found. Inspect the physical fabric for folds, holes and unsuitable material before cutting.'}</p><p>${omitted?'This material is currently excluded from every cutting plan.':'This material is available to the cutting solver.'}</p><button class="primary-button dialog-action" id="exclude-material">${omitted?'Include this material again':'Exclude from cutting'}</button>`,'REVIEW YOUR MATERIALS');$('exclude-material').onclick=async()=>{omitted?state.excluded.delete(s.id):state.excluded.add(s.id);$('info-dialog').close();await replan();toast(omitted?'Material included in the new plan.':'Material excluded. The cutting plan has been recalculated.');};}
  $('review-materials').onclick=()=>{if(!state.analysis)return toast('Analyze a photo to review its materials.');modal('You know your materials best.',`<p>Exclude uncertain or unsuitable scraps, then let the solver adjust. Select a piece to inspect its measured area and quality flags.</p><div class="material-review-list">${state.analysis.scraps.map(s=>`<button data-review="${esc(s.id)}"><i style="background:${esc(s.color)}"></i><strong>${esc(s.label)}</strong><span>${Math.round(s.areaCm2)} cm² · ${state.excluded.has(s.id)?'Excluded':'Included'}</span></button>`).join('')}</div>`,'HUMAN REVIEW, BETTER DESIGNS');$('dialog-content').querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>reviewMaterial(state.analysis.scraps.find(s=>s.id===b.dataset.review)));};
  let cloudReady=false,cloudSaving=false;
  function receipts(){try{return JSON.parse(localStorage.getItem('rethread-cloud-jobs')||'[]');}catch{return [];}}
  function encodeMask(mask){const output=[];for(let i=0;i<mask.length;){if(!mask[i]){i++;continue;}const start=i;while(i<mask.length&&mask[i])i++;output.push(start,i-start);}return output;}
  async function request(path,options={}){const c=new AbortController(),timer=setTimeout(()=>c.abort(),22000);try{const res=await fetch('/api/'+path,{...options,signal:c.signal,cache:'no-store'});const data=await res.json().catch(()=>({error:'The cloud service is unavailable.'}));if(!res.ok)throw new Error(data.error?.message||data.error||data.message||'The cloud request could not be completed.');return data;}catch(e){if(e.name==='AbortError')throw new Error('The cloud request took too long. Please try again.');throw e;}finally{clearTimeout(timer);}}
  async function saveTicket(body){const bytes=new TextEncoder().encode(JSON.stringify(body));const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),v=>v.toString(16).padStart(2,'0')).join('');let ticket;try{ticket=JSON.parse(localStorage.getItem('rethread-pending-save')||'null');}catch{}if(ticket?.signature!==hash){ticket={signature:hash,idempotencyKey:crypto.randomUUID(),accessToken:Array.from(crypto.getRandomValues(new Uint8Array(32)),v=>v.toString(16).padStart(2,'0')).join('')};localStorage.setItem('rethread-pending-save',JSON.stringify(ticket));}return ticket;}
  async function health(){try{const h=await request('ready');cloudReady=h.storageReady===true;$('cloud-status').textContent=cloudReady?'CONNECTED TO AZURE':'CLOUD STORAGE UNAVAILABLE';$('cloud-status').classList.toggle('connected',cloudReady);$('cloud-save').disabled=!cloudReady;$('cloud-detail').textContent=cloudReady?'Your photos stay local. Only derived shapes and design settings are sent for verification.':'The design studio works locally. Cloud saving becomes available on the Azure deployment.';}catch{$('cloud-status').textContent='LOCAL STUDIO';$('cloud-save').disabled=true;}}
  $('cloud-save').onclick=async()=>{if(cloudSaving||!state.analysis||!state.plan)return toast('Analyze a fabric photo first.');if(!cloudReady)return toast('Cloud saving is available on the Azure deployment.');cloudSaving=true;$('cloud-save').disabled=true;$('cloud-save').textContent='Verifying & saving…';try{const body=buildJobBody();const ticket=await saveTicket(body);const job=await request('jobs',{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':ticket.idempotencyKey,'X-ReThread-Token':ticket.accessToken},body:JSON.stringify(body)});if(!job.saved||!job.accessToken||!job.jobId)throw new Error('The service did not confirm a durable save.');const list=receipts().filter(j=>j.jobId!==job.jobId);list.unshift({jobId:job.jobId,accessToken:job.accessToken,title:job.plan?.title||state.plan.title,createdAt:job.createdAt,expiresAt:job.expiresAt});localStorage.setItem('rethread-cloud-jobs',JSON.stringify(list.slice(0,20)));localStorage.removeItem('rethread-pending-save');$('cloud-status').textContent='VERIFIED & SAVED';$('cloud-detail').textContent='Your derived cutting plan is saved privately for 30 days. This browser keeps its access key.';toast(job.plan?.feasible?'Cloud geometry verified. Your private plan is saved.':'The partial plan was saved with its incomplete status.');}catch(e){toast(e.message+' Your save key is kept here; retrying the same plan safely recovers a completed save.');}finally{cloudSaving=false;$('cloud-save').disabled=false;$('cloud-save').innerHTML='Cloud verify & save <span>↗</span>';}};
  $('cloud-history').onclick=()=>{const list=receipts();modal('Your plans, safely tucked away.',list.length?`<p>These private records are protected by keys kept in this browser. Records expire after 30 days; fabric photos are never stored in the cloud.</p>${list.map(j=>`<div class="cloud-record"><div><h3>${esc(j.title)}</h3><p>${j.createdAt?esc(new Date(j.createdAt).toLocaleString('en-IN')):'Saved plan'}</p></div><button data-cloud-open="${esc(j.jobId)}">View receipt ↗</button></div>`).join('')}`:'<p>Use <strong>Cloud verify & save</strong> to save a plan after the server checks its cutting geometry.</p>','YOUR PRIVATE PLAN ARCHIVE');$('dialog-content').querySelectorAll('[data-cloud-open]').forEach(b=>b.onclick=async()=>{const j=list.find(j=>j.jobId===b.dataset.cloudOpen);try{const report=await request('jobs/'+encodeURIComponent(j.jobId),{headers:{'X-ReThread-Token':j.accessToken}});const p=report.plan||report.job?.plan;modal('A plan you can trace.',`<p><strong>${esc(p?.title||j.title)}</strong><br>${p?.feasible?'Complete geometric layout':'Incomplete cutting layout'} · ${p?.pieces?.length||0} placed cuts<br>Saved: ${esc(report.createdAt||j.createdAt||'')}<br>Expires: ${esc(report.expiresAt||j.expiresAt||'')}</p><p>The server recomputed scale and material area from the supplied masks, validated constraints and stored the result in private Azure storage.</p>${report.analysisProvenance?.engine==='slimsam'?'<p><strong>Neural model:</strong> SlimSAM · pinned INT8 encoder and decoder. Inference ran locally; model provenance is reported by this browser.</p>':''}<p><strong>Input fingerprint:</strong> ${esc((report.inputDigest||'').slice(0,16))}…</p><button class="primary-button" id="cloud-download">Download cloud receipt · JSON</button><button class="text-button delete-record" id="cloud-delete">Delete this private record</button>`,'VERIFIED CUTTING RECEIPT');$('cloud-download').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='rethread-cloud-receipt.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),2000);};$('cloud-delete').onclick=async()=>{await request('jobs/'+encodeURIComponent(j.jobId),{method:'DELETE',headers:{'X-ReThread-Token':j.accessToken}});localStorage.setItem('rethread-cloud-jobs',JSON.stringify(receipts().filter(x=>x.jobId!==j.jobId)));$('info-dialog').close();toast('Private cloud record deleted.');};}catch(e){toast(e.message);}});};
  health();return {reviewMaterial,refreshCloud:health};
}
